package com.paitrick.blog.common.exception; import com.paitrick.blog.common.response.ApiResponse; import org.springframework.http.*; import org.springframework.web.bind.*; import org.springframework.web.bind.MethodArgumentNotValidException;
@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(BusinessException.class) ResponseEntity<ApiResponse<Void>> business(BusinessException e){return ResponseEntity.badRequest().body(new ApiResponse<>(400,e.getMessage(),null));}@ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiResponse<Void>> validation(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(new ApiResponse<>(400,e.getBindingResult().getFieldError().getDefaultMessage(),null));}@ExceptionHandler(Exception.class) ResponseEntity<ApiResponse<Void>> unknown(Exception e){return ResponseEntity.status(500).body(new ApiResponse<>(500,"internal server error",null));}}
